public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns a URL for chat revenue withdrawal; requires owner privileges in the channel chat or the bot. Currently, this method can be used only
    /// if getOption("can_withdraw_chat_revenue") for channels with supergroupFullInfo.can_get_revenue_statistics == true or bots with userFullInfo.bot_info.can_get_revenue_statistics == true
    /// </summary>
    public Task<TdLib.TdApi.Objects.HttpUrl> GetChatRevenueWithdrawalUrlAsync(long chatId = default, string password = default)
    {

           using var activity =  StartCallActivity("GetChatRevenueWithdrawalUrlAsync", typeof(GetChatRevenueWithdrawalUrl).FullName ?? "GetChatRevenueWithdrawalUrlAsync");

           try
           {
             return client.GetChatRevenueWithdrawalUrlAsync(chatId, password);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
